<script>
 import { onMount } from 'svelte';
 import { LayoutDashboard, ChartNoAxesColumn, FilePlus2, FileText, Search, RefreshCw, Download, X, LogOut, ArrowRight, AlertCircle, CheckCircle2 } from 'lucide-svelte';
 let role=$state('operator'), settings=$state({}), settingsVersion=$state(''), requests=$state([]), notifications=$state([]), saving=$state(false), requestBusy=$state(false), chosenRequests=$state([]), reviewReason=$state('Reviewed previous replacement'), employeeSyncBusy=$state(false);
 let token=$state(sessionStorage.getItem('did_token')||''); let loginEmail=$state(''); let loginPin=$state(''); let loginOtp=$state(''); let challengeId=$state(''); let loginBusy=$state(false); let loginError=$state('');
 let dids=$state([]), query=$state(''), type=$state('active'), assignment=$state('all'), operator=$state('all');
 let tab=$state('Dashboard'), selected=$state(null), busy=$state(false), loading=$state(false), error=$state(''), notice=$state(''), configured=$state(false);
 let inventoryStatus=$state(null), initialSyncBusy=$state(false), settingsLoaded=$state(false), settingsDirty=$state(false);
 let selectedDids=$state([]), batch=$state(null), batchBusy=$state(false), batchError=$state(''), queueItems=$state([]), currentQueueId=$state('');
 let date=$state(new Date().toISOString().slice(0,10)); let replacement=$state(''); let page=$state(1); const pageSize=50;
 let normalizedQuery=$derived(query.trim().toLowerCase());
 let filtered=$derived(dids.filter(d=>(type==='all'||d.status===type)&&(type!=='active'||assignment==='all'||(assignment==='assigned'?!!d.agent_number:!d.agent_number))&&(type!=='active'||operator==='all'||d.operator===operator)&&`${d.did} ${d.agent||''} ${d.agent_number||''} ${d.operator||''}`.toLowerCase().includes(normalizedQuery)));
 let pageItems=$derived(filtered.slice((page-1)*pageSize,page*pageSize));
 let operators=$derived([...new Set(dids.map(d=>d.operator).filter(Boolean))].sort());
 let pool=$derived(dids.filter(d=>d.status==='pool'));
 let active=$derived(dids.filter(d=>d.status==='active'));
 let counsellors=$derived(active.filter(d=>d.agent_number && d.agent?.toLowerCase()!=='common pool').length);
 let activeCommonPool=$derived(active.filter(d=>!d.agent_number || d.agent?.toLowerCase()==='common pool').length);
 let categoryItems=$derived(dids.filter(d=>type==='all'||d.status===type));
 let duplicateCount=$derived(filtered.filter(d=>d.duplicate).length);
 let proposed=$derived(pool.find(d=>d.did===replacement));
 function toggleDid(d){selectedDids=selectedDids.includes(d)?selectedDids.filter(x=>x!==d):[...selectedDids,d]}
 async function startBatch(){if(batchBusy||!selectedDids.length)return;batchError='';batchBusy=true;try{const x=await api('/api/reassign',{method:'POST',body:JSON.stringify({dids:selectedDids})});currentQueueId=x.queue_id;batch=x;await pollBatch()}catch(e){batchError=String(e.message);batchBusy=false}}
 async function pollBatch(){while(token){try{const x=await api('/api/queue');queueItems=x.items||[];const mine=queueItems.find(q=>q.queue_id===currentQueueId);if(!mine||['completed','needs_reconciliation','cancelled'].includes(mine.status)){batchBusy=false;selectedDids=[];if(mine?.status==='needs_reconciliation')batchError='Operation needs administrator reconciliation';await refresh(false);return}batch={...mine,running:mine.status==='processing'};}catch(e){batchError='Unable to read queue. Check audit and recovery before retrying.';batchBusy=false;return}await new Promise(resolve=>setTimeout(resolve,3000))}}
 async function readApiResponse(response){
  const raw=await response.text();let parsed;
  try{parsed=raw?JSON.parse(raw):{}}catch{
   throw Error(`Server returned HTTP ${response.status} instead of JSON. Check Render logs for the underlying error.`);
  }
  if(!response.ok){const detail=parsed?.detail;throw Error(typeof detail==='string'?detail:detail?.message||`Request failed (HTTP ${response.status})`)}
  return parsed;
 }
 async function api(path,opts={}){const r=await fetch(path,{...opts,headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json',...(opts.headers||{})}});return readApiResponse(r)}
 async function loadRole(){try{role=(await api('/api/me')).role}catch(e){error=e.message}}
 async function loadSettings(){error='';try{let x=await api('/api/settings');settings=x.settings;settingsVersion=x.version;settingsLoaded=true;settingsDirty=false;notice='Settings loaded from Google Sheets.'}catch(e){error='Settings could not be loaded: '+e.message}}
 async function saveSettings(){saving=true;error='';notice='';try{
  const x=await api('/api/settings',{method:'PUT',body:JSON.stringify({settings,version:settingsVersion})});
  const verified=await api('/api/settings');
  if(verified.version!==x.version)throw Error('Settings saved but read-back version differs. Reload and inspect Google Sheets.');
  settings=verified.settings;settingsVersion=verified.version;settingsDirty=false;
  notice=`Settings saved and verified in Google Sheets (${x.changed} changes).`;
 }catch(e){error=`Settings not confirmed: ${e.message}`;}finally{saving=false}}
 async function loadRequests(){try{requests=(await api('/api/requests')).items;notifications=(await api('/api/notifications')).items}catch(e){error=e.message}}
 async function autoSync(){try{await syncRequests();await runReminders()}catch(e){error=e.message}}
 async function syncRequests(){requestBusy=true;error='';try{let x=await api('/api/requests/sync',{method:'POST'});notice=`Imported ${x.created} new requests and ${x.repeated} repeat calls.`;await loadRequests()}catch(e){error=e.message}finally{requestBusy=false}}
 async function syncEmployees(){employeeSyncBusy=true;try{let x=await api('/api/employees/sync',{method:'POST'});notice=`Employee directory updated: ${x.count} agents.`}catch(e){error=e.message}finally{employeeSyncBusy=false}}
 async function runReminders(){requestBusy=true;try{let x=await api('/api/reminders/run',{method:'POST'});notice=`Processed ${x.processed||0} due reminders.`;await loadRequests()}catch(e){error=e.message}finally{requestBusy=false}}
 async function reviewRequest(r,approved){try{await api(`/api/requests/${r.request_id}/review`,{method:'POST',body:JSON.stringify({approved,reason:reviewReason})});await loadRequests()}catch(e){error=e.message}}
 async function replaceRequests(){if(!chosenRequests.length)return;batchBusy=true;batchError='';try{let x=await api('/api/requests/reassign',{method:'POST',body:JSON.stringify({request_ids:chosenRequests})});batch=x;currentQueueId=x.queue_id;await pollBatch();chosenRequests=[];await loadRequests()}catch(e){batchError=e.message;batchBusy=false}}
 async function signin(){loginBusy=true;loginError='';try{const r=await fetch('/api/auth/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:loginEmail,pin:loginPin})});const x=await r.json();if(!r.ok)throw Error(x.detail||'Unable to send OTP');challengeId=x.challenge_id;loginPin=''}catch(e){loginError=e.message}finally{loginBusy=false}}
 async function verifyOtp(){const cleanOtp=String(loginOtp).replace(/\D/g,'').slice(0,6);loginOtp=cleanOtp;if(!/^[0-9]{6}$/.test(cleanOtp)){loginError='Please enter a valid 6-digit OTP.';return;}loginBusy=true;loginError='';try{const r=await fetch('/api/auth/verify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({challenge_id:challengeId,otp:cleanOtp})});const x=await r.json();if(!r.ok)throw Error(x.detail||'OTP verification failed');token=x.token;sessionStorage.setItem('did_token',token);loginOtp='';refresh();loadRole();loadRequests()}catch(e){loginError=e.message}finally{loginBusy=false}}
 function openTab(next){tab=next;if(next==='Settings')loadSettings()}
 function signout(){sessionStorage.removeItem('did_token');token='';dids=[];}
 async function refresh(force=false){loading=true;error='';try{
  inventoryStatus=await api('/api/inventory/status');
  if(force){await api('/api/sync',{method:'POST'});}
  const data=await api('/api/dids');configured=!!data.configured;
  dids=(data.items||[]).map(d=>({...d,status:String(d.status||'unknown').toLowerCase()}));
  notice=force?`DID inventory refreshed (${dids.length} records).`:notice;
  if(force)inventoryStatus=await api('/api/inventory/status');
 }catch(e){error=`DID inventory could not be loaded: ${e.message}`;}finally{loading=false}}
 onMount(()=>{if(token){refresh();loadRole();loadRequests();api('/api/queue').then(x=>{queueItems=x.items||[]}).catch(()=>{})}const handler=e=>{if(batchBusy){e.preventDefault();e.returnValue='A DID batch is in progress'}};const visibility=()=>{if(document.hidden&&batchBusy)notice='Bulk processing continues on the server. Return to this tab to monitor progress.'};window.addEventListener('beforeunload',handler);document.addEventListener('visibilitychange',visibility);return()=>{window.removeEventListener('beforeunload',handler);document.removeEventListener('visibilitychange',visibility)}});
 function openAction(d,action){selected={...d,action};replacement='';date=new Date().toISOString().slice(0,10)}
 async function initializeInventory(){initialSyncBusy=true;try{await refresh(true)}finally{initialSyncBusy=false}}
 function changeSetting(key,value){settings={...settings,[key]:value};settingsDirty=true;notice=''}
 async function execute(){if(!selected||busy)return;busy=true;error='';notice='';try{let r=await fetch(`/api/did/${selected.action}`,{method:'POST',headers:{Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify({did:selected.did,agent:selected.agent||null})});let data=await r.json();if(!r.ok)throw Error(data.detail||'MCube operation failed');dids=dids.map(d=>d.did===selected.did?{...d,status:selected.action==='activate'?'active':'inactive'}:d);notice=`${selected.did}: ${selected.action} request accepted by MCube. Verify live status.`;selected=null;}catch(e){error=e.message}finally{busy=false}}
 function exportCSV(){let cols=type==='active'?['did','agent','agent_number','operator','status']:['did','operator','status'];let lines=[cols.join(','),...filtered.map(d=>cols.map(c=>'"'+String(d[c]??'').replaceAll('"','""')+'"').join(','))];let a=document.createElement('a');let u=URL.createObjectURL(new Blob(['\uFEFF'+lines.join('\r\n')],{type:'text/csv;charset=utf-8'}));a.href=u;a.download=`mcube-dids-${type}.csv`;a.click();URL.revokeObjectURL(u)}
</script>
<svelte:head><title>MCube | DID Number Management</title><meta name="description" content="MCube DID management workspace"/></svelte:head>
{#if !token}
 <main class="login"><form class="login-card" onsubmit={e=>{e.preventDefault();challengeId?verifyOtp():signin()}}><div class="logo">▦</div><h1>DID Number Management</h1><p>Secure email OTP + PIN sign in</p>
 {#if !challengeId}
 <label>Authorized email</label><input type="email" bind:value={loginEmail} placeholder="Your work email" required autocomplete="username"/>
 <label>PIN</label><input type="password" inputmode="numeric" minlength="4" maxlength="12" bind:value={loginPin} placeholder="Enter PIN" required autocomplete="current-password"/>
 {:else}
 <p>Enter the 6-digit code sent to {loginEmail}. It expires in 5 minutes.</p><label>One-time password</label><input type="text" inputmode="numeric" maxlength="6" bind:value={loginOtp} oninput={(e)=>{loginOtp=e.currentTarget.value.replace(/\D/g,'').slice(0,6)}} placeholder="6-digit OTP" required autocomplete="one-time-code"/>
 <button type="button" class="outline" onclick={()=>{challengeId='';loginOtp='';loginError=''}}>Back to login</button>
 {/if}
 {#if loginError}<p role="alert" style="color:#b91c1c">{loginError}</p>{/if}
 <button class="primary" disabled={loginBusy}>{loginBusy?'Please wait…':challengeId?'Verify OTP & sign in':'Send OTP'} <ArrowRight size={17}/></button></form></main>
{:else}
 <div class="app"><header class="topbar"><div class="brand"><span class="brand-mark">▦</span><span>MCube <b>DID Manager</b></span></div><nav>{#each [{name:'Dashboard',icon:LayoutDashboard},{name:'Analytics',icon:ChartNoAxesColumn},{name:'Request',icon:FilePlus2},{name:'Report',icon:FileText},...(role==='admin'?[{name:'Settings',icon:FileText}]:[])] as n}<button class:current={tab===n.name} disabled={batchBusy} onclick={()=>openTab(n.name)}><n.icon size={18}/>{n.name}</button>{/each}</nav><button class="logout" disabled={batchBusy} onclick={signout}><LogOut size={17}/> <span>Sign out</span></button></header>
 <main class="container">
 {#if error}<div class="message error"><AlertCircle size={17}/>{error}<button onclick={()=>error=''}><X size={16}/></button></div>{/if}
 {#if notice}<div class="message success"><CheckCircle2 size={17}/>{notice}<button onclick={()=>notice=''}><X size={16}/></button></div>{/if}

 {#if tab==='Dashboard'}
 {#if inventoryStatus && !inventoryStatus.initialized && tab==='Dashboard'}
 <section class="setup-banner"><div><strong>First-time setup: DID inventory has not been imported</strong><p>Your Google Sheet is empty. Import active, inactive and pool DIDs from MCube before using the replacement queue. This only reads MCube and saves inventory snapshots; it does not replace DIDs or initiate calls.</p></div><button class="primary" disabled={loading||initialSyncBusy||batchBusy} onclick={initializeInventory}>{initialSyncBusy?'Importing inventory…':'Import MCube DID inventory'}</button></section>
{:else if inventoryStatus?.initialized && tab==='Dashboard'}
 <div class="sync-caption">Last successful MCube inventory import: {inventoryStatus.last_sync_utc} · Active {inventoryStatus.counts?.active??0} · Inactive {inventoryStatus.counts?.inactive??0} · Pool {inventoryStatus.counts?.pool??0}</div>
{/if}
<div class="metrics"><div class="metric"><span>Total DIDs</span><strong>{categoryItems.length.toLocaleString()}</strong></div>{#if type==='active' || type==='all'}<div class="metric"><span>Counsellors</span><strong>{counsellors.toLocaleString()}</strong></div><div class="metric"><span>Common Pool (active response)</span><strong>{activeCommonPool.toLocaleString()}</strong></div>{/if}<div class="metric"><span>Filtered Results</span><strong>{filtered.length.toLocaleString()}</strong></div></div>
 <section class="filters"><label class="search-field">Search<div class="input-icon"><Search size={19}/><input bind:value={query} oninput={()=>page=1} placeholder={type==='active'?'DID, agent, mobile or operator':'DID number or operator'}/></div></label><label>DID Type<select bind:value={type} onchange={()=>{page=1;assignment='all';operator='all';selectedDids=[]}}><option value="active">Active</option><option value="inactive">Inactive</option><option value="pool">Pool</option></select></label>{#if type==='active'}<label>Assignment<select bind:value={assignment} onchange={()=>page=1}><option value="all">All DIDs</option><option value="assigned">Assigned</option><option value="unassigned">Unassigned</option></select></label><label>Operator<select bind:value={operator} onchange={()=>page=1}><option value="all">All operators</option>{#each operators as o}<option value={o}>{o}</option>{/each}</select></label>{/if}<button class="primary export" onclick={exportCSV}><Download size={17}/> Download CSV</button></section>
 <div class="result-bar">{#if type==='active'}<span><b>{selectedDids.length} selected</b> / {pool.length} available pool DIDs <button class="primary" disabled={batchBusy||!selectedDids.length||selectedDids.length>pool.length} onclick={startBatch}>{batchBusy?'Processing batch…':'Reassign selected (FIFO)'}</button></span>{/if}<span>{loading?'Loading DID records…':`${filtered.length.toLocaleString()} ${type} DID records displayed.`}</span><button class="outline" onclick={()=>refresh(true)} disabled={loading||batchBusy}><RefreshCw size={16} class={loading ? 'spin' : ''}/> Refresh</button></div>
 {#if duplicateCount}<div class="message error">{duplicateCount} displayed rows have repeated DID numbers within this category. These records are highlighted for review; inventory is not blocked.</div>{/if}
 {#if batchBusy}<div class="message success">Bulk reassignment running: {batch?.done||0} / {batch?.total||selectedDids.length}. Navigation and DID controls are locked until processing finishes. Keep this tab open.</div>{/if}
 {#if batchError}<div class="message error">{batchError}</div>{/if}
 {#if batch?.error}<div class="message error">Batch stopped: {batch.error}. Review Change_Logs before retrying.</div>{/if}
 <div class="table-card"><div class="table-scroll"><table><thead><tr>{#if type==='active'}<th>SELECT</th>{/if}<th>SL. NO.</th><th>DID NUMBER</th>{#if type==='active'}<th>AGENT NAME</th><th>AGENT NUMBER</th>{/if}<th>OPERATOR</th><th>STATUS</th>{#if type==='active'}<th>ACTION</th>{/if}</tr></thead><tbody>{#each pageItems as d,i (`${d.status}-${d.did}-${(page-1)*pageSize+i}`)}<tr class:duplicate-row={d.duplicate}>{#if type==='active'}<td>{#if d.agent_number && !d.duplicate}<input type="checkbox" checked={selectedDids.includes(d.did)} disabled={batchBusy||(!selectedDids.includes(d.did)&&selectedDids.length>=pool.length)} onchange={()=>toggleDid(d.did)}/>{/if}</td>{/if}<td>{(page-1)*pageSize+i+1}</td><td class="number">{d.did}{#if d.duplicate}<span class="duplicate-label" title="Repeated DID in this category">Duplicate</span>{/if}</td>{#if type==='active'}<td>{d.agent||'—'}</td><td>{d.agent_number||'—'}</td>{/if}<td>{d.operator||'—'}</td><td><span class="pill {d.status}">{d.status==='active'?(d.agent_number?'Counsellors':'Common pool'):d.status==='pool'?'Pool':'Inactive'}</span></td>{#if type==='active'}<td>{#if d.agent_number && !d.duplicate}<button class="action" disabled={batchBusy} onclick={()=>{selectedDids=[d.did];startBatch()}}>↻ Reassign</button>{/if}</td>{/if}</tr>{:else}<tr><td colspan={type==='active'?8:4} class="empty">{loading?'Loading…':'No DID records found.'}</td></tr>{/each}</tbody></table></div><div class="pagination"><span>Showing {filtered.length?((page-1)*pageSize+1):0}–{Math.min(page*pageSize,filtered.length)} of {filtered.length}</span><div><button class="outline" disabled={page===1} onclick={()=>page--}>Previous</button><span>Page {page}</span><button class="outline" disabled={page*pageSize>=filtered.length} onclick={()=>page++}>Next</button></div></div></div>
 {:else if tab==='Request'}
 <section class="filters"><h2>Incoming replacement requests</h2><button class="primary" disabled={requestBusy||batchBusy} onclick={syncRequests}>Sync request calls</button><button class="outline" disabled={requestBusy||batchBusy} onclick={runReminders}>Check due reminders</button><button class="outline" onclick={loadRequests}>Refresh queue</button></section>
 <div class="metrics"><div class="metric"><span>Pending / Approved</span><strong>{requests.filter(r=>['pending','approved'].includes(r.status)).length}</strong></div><div class="metric"><span>Recent repeat review</span><strong>{requests.filter(r=>r.status==='review_required').length}</strong></div><div class="metric"><span>Completed</span><strong>{requests.filter(r=>r.status==='completed').length}</strong></div><div class="metric"><span>Needs reconciliation</span><strong>{requests.filter(r=>r.status==='needs_reconciliation').length}</strong></div></div>
 <div class="result-bar"><b>{chosenRequests.length} selected</b><button class="primary" disabled={batchBusy||!chosenRequests.length} onclick={replaceRequests}>Replace selected (FIFO)</button></div>
 <div class="table-card"><div class="table-scroll"><table><thead><tr><th>Select</th><th>Agent</th><th>Mobile</th><th>Current DID</th><th>First call</th><th>Last call</th><th>Calls</th><th>Status</th><th>Action</th></tr></thead><tbody>{#each requests as r (r.request_id)}<tr><td><input type="checkbox" disabled={batchBusy||!['pending','approved'].includes(r.status)} checked={chosenRequests.includes(r.request_id)} onchange={()=>chosenRequests=chosenRequests.includes(r.request_id)?chosenRequests.filter(x=>x!==r.request_id):[...chosenRequests,r.request_id]}/></td><td>{r.agent_name||'—'}</td><td>{r.agent_number}</td><td>{r.current_did}</td><td>{r.first_call_utc}</td><td>{r.last_call_utc}</td><td>{r.call_count}</td><td><span class="pill {r.status==='completed'?'active':r.recent_warning==='yes'?'inactive':'pool'}">{r.status}{r.recent_warning==='yes'?' · recent replacement':''}</span></td><td>{#if role==='admin' && r.status==='review_required'}<button class="action" onclick={()=>reviewRequest(r,true)}>Approve</button><button class="action danger" onclick={()=>reviewRequest(r,false)}>Reject</button>{/if}</td></tr>{:else}<tr><td colspan="9">No requests yet. Sync inbound calls to import qualifying requests.</td></tr>{/each}</tbody></table></div></div>
 {#if batchBusy}<div class="message success">Sequential replacement running. Do not initiate another batch.</div>{/if}
 {#if batchError}<div class="message error">{batchError}</div>{/if}
 {:else if tab==='Settings'}
 <div class="settings-header"><div><h1>Application settings</h1><p>Manage MCube connectivity, replacement rules and notifications. Changes are saved to Google Sheets only when you click Save.</p></div><div class="settings-actions"><button class="outline" disabled={saving} onclick={loadSettings}>Reload from Sheets</button>{#if role==='admin'}<button class="primary" disabled={saving||batchBusy||!settingsLoaded||!settingsDirty} onclick={saveSettings}>{saving?'Saving and verifying…':'Save changes'}</button>{/if}</div></div>
 {#if role!=='admin'}<div class="message error">Settings are read-only for operators.</div>{/if}
 {#if !settingsLoaded}<div class="message error">Settings have not loaded successfully. Do not edit or save until Google Sheets is accessible.</div>{/if}
 {#if settingsDirty}<div class="unsaved-indicator">You have unsaved changes. Reload discards them.</div>{/if}
 <div class="settings-layout">
  <section class="settings-section"><div class="section-heading"><h2>MCube and request intake</h2><p>Numbers and call-log import behavior</p></div><div class="settings-fields">
  {#each [{key:'request_did',label:'Replacement request DID',hint:'Inbound calls to this DID can create replacement requests'},{key:'call_page_size',label:'Call-log page size',numeric:true,min:1},{key:'employee_refresh_hours',label:'Employee refresh interval (hours)',numeric:true,min:1},{key:'recent_replacement_days',label:'Recent replacement warning (days)',numeric:true,min:1}] as field}<label class="setting-field"><span>{field.label}</span><input disabled={role!=='admin'||!settingsLoaded} type={field.numeric?'number':'text'} min={field.min} value={settings[field.key]??''} oninput={e=>changeSetting(field.key,field.numeric?Number(e.currentTarget.value):e.currentTarget.value)}/>{#if field.hint}<small>{field.hint}</small>{/if}</label>{/each}
  <label class="setting-field"><span>Request synchronization</span><select disabled={role!=='admin'||!settingsLoaded} value={settings.sync_mode||'manual'} onchange={e=>changeSetting('sync_mode',e.currentTarget.value)}><option value="manual">Manual only</option><option value="login">On application login</option></select></label>
  </div></section>
  <section class="settings-section"><div class="section-heading"><h2>Replacement safety</h2><p>Protect agents against accidental repeat replacements</p></div><div class="settings-toggle-list"><label class="setting-toggle"><input type="checkbox" disabled={role!=='admin'||!settingsLoaded} checked={!!settings.require_recent_review} onchange={e=>changeSetting('require_recent_review',e.currentTarget.checked)}/><span><b>Administrator review for recent replacements</b><small>Require approval for replacements within the configured warning period.</small></span></label></div></section>
  <section class="settings-section"><div class="section-heading"><h2>Outbound call notifications</h2><p>Leave these disabled until MCube calling is tested and approved.</p></div><div class="settings-fields">
  {#each [{key:'outbound_caller_number',label:'Outbound caller (exenumber)'},{key:'first_contact_number',label:'First reminder recipient'},{key:'second_contact_number',label:'Escalation recipient'},{key:'reminder_first_minutes',label:'First reminder delay (minutes)',numeric:true},{key:'reminder_interval_minutes',label:'Repeat interval (minutes)',numeric:true},{key:'reminder_escalation_minutes',label:'Escalation delay (minutes)',numeric:true},{key:'reminder_max_attempts',label:'Maximum attempts',numeric:true}] as field}<label class="setting-field"><span>{field.label}</span><input disabled={role!=='admin'||!settingsLoaded} type={field.numeric?'number':'text'} min={field.numeric?0:undefined} value={settings[field.key]??''} oninput={e=>changeSetting(field.key,field.numeric?Number(e.currentTarget.value):e.currentTarget.value)}/></label>{/each}
  </div><div class="settings-toggle-list">{#each [{key:'reminder_enabled',label:'Enable periodic reminder calls'},{key:'notify_on_queue',label:'Call first recipient on queue entry'},{key:'notify_on_completion',label:'Call agent after replacement'}] as field}<label class="setting-toggle"><input type="checkbox" disabled={role!=='admin'||!settingsLoaded} checked={!!settings[field.key]} onchange={e=>changeSetting(field.key,e.currentTarget.checked)}/><span><b>{field.label}</b></span></label>{/each}</div></section>
  <section class="settings-section"><div class="section-heading"><h2>Email and Brevo</h2><p>Brevo credentials remain private in Render environment variables</p></div><div class="settings-fields">{#each [{key:'admin_email',label:'Administrator notification email'},{key:'mail_from',label:'Notification sender address'}] as field}<label class="setting-field"><span>{field.label}</span><input disabled={role!=='admin'||!settingsLoaded} type="email" value={settings[field.key]??''} oninput={e=>changeSetting(field.key,e.currentTarget.value)}/></label>{/each}<label class="setting-field"><span>Mail provider</span><select disabled={role!=='admin'||!settingsLoaded} value={settings.mail_provider||'disabled'} onchange={e=>changeSetting('mail_provider',e.currentTarget.value)}><option value="disabled">Disabled</option><option value="brevo">Brevo API</option></select></label></div><div class="settings-toggle-list">{#each [{key:'email_on_queue',label:'Email agent when queued'},{key:'email_on_completion',label:'Email agent when completed'}] as field}<label class="setting-toggle"><input type="checkbox" disabled={role!=='admin'||!settingsLoaded} checked={!!settings[field.key]} onchange={e=>changeSetting(field.key,e.currentTarget.checked)}/><span><b>{field.label}</b></span></label>{/each}</div></section>
  <section class="settings-section"><div class="section-heading"><h2>Employee directory</h2><p>Import minimal employee fields for request matching and email notifications</p></div><button class="outline" disabled={employeeSyncBusy||batchBusy} onclick={syncEmployees}>{employeeSyncBusy?'Refreshing employees…':'Refresh employee directory'}</button></section>
 </div>
 <div class="settings-footer"><span>{settingsDirty?'Unsaved changes':'All loaded changes are saved'}</span>{#if role==='admin'}<button class="primary" disabled={saving||batchBusy||!settingsLoaded||!settingsDirty} onclick={saveSettings}>{saving?'Saving…':'Save changes to Google Sheets'}</button>{/if}</div>
 {:else}<div class="placeholder"><h1>{tab}</h1><p>{tab==='Request'?'DID replacement requests and approvals will appear here once the workflow API is configured.':tab==='Report'?'Operation history and exportable reports require persistent audit storage.':'Charts and usage analytics will appear after live DID data is connected.'}</p><button class="outline" onclick={()=>tab='Dashboard'}>Back to Dashboard</button></div>{/if}
 </main></div>
{/if}
{#if selected}<div class="overlay" role="presentation" onclick={e=>{if(e.target===e.currentTarget&&!busy)selected=null}}><section class="modal" role="dialog" aria-modal="true" aria-label="DID operation"><button class="close" onclick={()=>selected=null} disabled={busy}><X size={20}/></button><h2>{selected.action==='reassign'?'Reassign DID':selected.action==='activate'?'Activate DID':'Deactivate DID'}</h2><p class="subtitle">{selected.action==='reassign'?'Deactivate the current DID and activate a compatible common-pool DID for this agent.':'Review the details before sending the request to MCube.'}</p><div class="detail"><h3>CURRENT ASSIGNMENT</h3><p><b>Agent:</b> {selected.agent||'Unassigned'}</p><p><b>Agent number:</b> {selected.agent_number||'—'}</p><p><b>Current DID:</b> {selected.did}</p><p><b>Operator:</b> {selected.operator||'—'}</p></div>{#if selected.action==='reassign'}<div class="detail"><h3>WILL REASSIGN TO</h3><label>Replacement DID<select bind:value={replacement}><option value="">Select available pool DID</option>{#each pool as d}<option value={d.did}>{d.did} — {d.operator||'Unknown operator'}</option>{/each}</select></label>{#if proposed}<p><b>Operator:</b> {proposed.operator||'—'}</p>{/if}<label>Replacement request date<input type="date" bind:value={date}/></label><p class="warning">Automatic reassignment is disabled until both MCube API payloads and success responses are verified. This prevents accidental partial reassignment.</p></div>{/if}<div class="modal-actions"><button class="outline" onclick={()=>selected=null} disabled={busy}>Cancel</button>{#if selected.action==='reassign'}<button class="primary" disabled>API mapping required</button>{:else}<button class="primary" disabled={busy} onclick={execute}>{busy?'Processing…':`Confirm ${selected.action}`}</button>{/if}</div></section></div>{/if}
